/**
 * Bundles the compiled schema validators and the cross-credential
 * validator into a single self-contained ES module.
 *
 * Usage: node compile-schemas.js && node bundle-validator.js
 * Output: ../gs1-license-validation.js
 */

const fs = require('fs');
const path = require('path');

const COMPILED_SCHEMAS = path.resolve(__dirname, '../compiled-schemas.cjs');
const CROSS_CREDENTIAL_RULES = path.resolve(__dirname, 'cross-credential-rules.js');
const OUTPUT = path.resolve(__dirname, '../gs1-license-validation.mjs');

const compiledCode = fs.readFileSync(COMPILED_SCHEMAS, 'utf-8');
const rulesCode = fs.readFileSync(CROSS_CREDENTIAL_RULES, 'utf-8');

const header = `/**
 * GS1 License Validation — JavaScript credential validator per W3C
 * Recognized Entities v1.0 §3.5.2 and §4.4.1.
 *
 * This file is the single credentialValidator for all GS1 license
 * credential types. It combines:
 *   1. Compiled JSON Schema structural validation (from AJV)
 *   2. Cross-credential field constraint checks
 *   3. Chain continuity enforcement (digest-based)
 *
 * Generated by: build/bundle-validator.js
 * Do not edit directly — edit the source schemas and cross-credential
 * rules, then rebuild.
 */

`;

// Wrap the CJS compiled schemas in an IIFE
const schemaBlock = `// --- Compiled schema validators (AJV standalone output) ---
const _schemaValidators = (function() {
  const module = {exports: {}};
  const exports = module.exports;
  ${compiledCode}
  return module.exports;
})();

`;

const bundle = header + schemaBlock + rulesCode;

fs.writeFileSync(OUTPUT, bundle, 'utf-8');
const stats = fs.statSync(OUTPUT);
console.log(`Bundled validator written to: ${OUTPUT}`);
console.log(`Size: ${(stats.size / 1024).toFixed(1)} KB`);
